1	# Validate the repository-wide SDD workflow state. Keep rule IDs in parity with Bash.
2	$ErrorActionPreference = "Stop"
3	
4	# WFI-021: diagnostics accumulate across independent features instead of
5	# exiting at the first one. Inside a feature's validation scope
6	# Stop-WorkflowState throws a sentinel the per-feature loop catches (so the
7	# short-circuit WITHIN a feature is retained); outside feature scope it
8	# still exits immediately. The run exits non-zero at the end if any fired.
9	$script:WorkflowStateFailed = 0
10	$script:FeatureScopeActive = $false
11	$script:WorkflowStateFeatureAbort = "workflow-state-feature-abort"
12	function Write-WorkflowStateDiagnostic([string]$Feature, [string]$Rule, [string]$Message) {
13	    [Console]::Error.WriteLine("workflow-state: ${Feature}: ${Rule}: ${Message}")
14	}
15	function Stop-WorkflowState([string]$Feature, [string]$Rule, [string]$Message) {
16	    Write-WorkflowStateDiagnostic $Feature $Rule $Message
17	    if ($script:FeatureScopeActive) { throw $script:WorkflowStateFeatureAbort }
18	    exit 1
19	}
20	function Get-Sha256([string]$Path) {
21	    return (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()
22	}
23	# plugins/ reference docs (risk-gate-matrix.md, reviewer-calibration.md, etc.)
24	# evolve normally over time, but historical review evidence under reports/
25	# records the sha256 that was current when that evidence was produced. A
26	# later, legitimate edit to a reference doc must not retroactively fail every
27	# past feature's provenance. When a manifest-recorded hash for a plugins/
28	# path does not match the live working-tree file, fall back to resolving the
29	# file's content as of the commit that INTRODUCED the specific evidence file
30	# being validated (the review contract JSON itself is immutable, committed
31	# historical fact) and accept the match only if it is identical. The pin
32	# stands in for "when this review happened" -- a moment that does not move
33	# when the record is later amended for an unrelated reason, so this resolves
34	# --diff-filter=A (the commit that added the path), not the commit that most
35	# recently touched it: a subsequent, unrelated edit to the same contract
36	# (e.g. a provenance re-bind) must not retroactively shift the pin forward
37	# past reference-doc evolution that happened in between, which would falsely
38	# invalidate a hash that was valid when the review actually ran.
39	# This keeps tamper detection intact: a forged hash that matches no
40	# legitimate point-in-time content still fails.
41	function Get-PluginsPinCommit([string]$EvidenceFile) {
42	    if (-not (Get-Command git -ErrorAction SilentlyContinue)) { return $null }
43	    & git -C $ScriptRoot rev-parse --is-inside-work-tree *> $null
44	    if ($LASTEXITCODE -ne 0) { return $null }
45	    $prefix = $RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
46	    if (-not $EvidenceFile.StartsWith($prefix, [StringComparison]::Ordinal)) { return $null }
47	    $relative = $EvidenceFile.Substring($prefix.Length).Replace("\", "/")
48	    # A path added, deleted, and re-added yields more than one
49	    # --diff-filter=A commit (captured here as an array); a path that has
50	    # never been committed (working-tree only) yields none ($null/empty).
51	    # Both are an indeterminate introducing commit. Since this is a
52	    # provenance check, failing closed on an indeterminate pin is safer than
53	    # guessing which addition -- or accepting a convenient one -- is
54	    # authoritative.
55	    $result = & git -C $ScriptRoot log --diff-filter=A --format='%H' -- $relative 2>$null
56	    if ($LASTEXITCODE -ne 0 -or -not $result) { return $null }
57	    if ($result -is [array]) { return $null }
58	    return [string]$result
59	}
60	function Get-PluginsHashAtPin([string]$Pin, [string]$PluginsRelative) {
61	    if (-not $Pin) { return $null }
62	    & git -C $ScriptRoot merge-base --is-ancestor $Pin HEAD 2>$null
63	    if ($LASTEXITCODE -ne 0) { return $null }
64	    # Redirect the blob straight to a temp file and hash the file so the
65	    # comparison is byte-exact -- capturing external-command stdout through
66	    # the PowerShell pipeline splits it into lines and can alter encoding or
67	    # trailing newlines, which would corrupt the sha256.
68	    $tempFile = [IO.Path]::GetTempFileName()
69	    try {
70	        & git -C $ScriptRoot show "${Pin}:${PluginsRelative}" > $tempFile 2>$null
71	        if ($LASTEXITCODE -ne 0) { return $null }
72	        return (Get-FileHash -LiteralPath $tempFile -Algorithm SHA256).Hash.ToLowerInvariant()
73	    } finally {
74	        Remove-Item -LiteralPath $tempFile -Force -ErrorAction SilentlyContinue
75	    }
76	}
77	# Returns $true when $ScriptRoot has any git history to consult at all (git
78	# binary present and it is a work tree). Checked independently of
79	# Get-PluginsPinCommit's own return value, because that function also
80	# returns $null for reasons that are NOT "no history exists" (e.g. an
81	# evidence path outside $RepoRoot, or a path with no commits) -- only the
82	# true absence of git history should relax Test-PluginsHashMatches below.
83	function Test-PluginsGitHistoryAvailable() {
84	    if (-not (Get-Command git -ErrorAction SilentlyContinue)) { return $false }
85	    & git -C $ScriptRoot rev-parse --is-inside-work-tree *> $null
86	    return $LASTEXITCODE -eq 0
87	}
88	# Returns $true if $PluginsFile's content matches $Expected either right
89	# now, or as of the commit that produced $EvidenceFile (the review contract
90	# JSON whose recorded manifest hash is being validated). A release artifact
91	# (e.g. the tarball repository-release-validation.tests.sh builds) carries no
92	# .git directory, so there is no history there to reconcile a
93	# manifest-recorded hash against: the comparison is not evaluable rather than
94	# failed, and is accepted for this plugins/* shared-reference class only.
95	# The same assertion is still fully enforced by every git-bearing run of this
96	# script (in place, in CI checkouts, in this repo's own fixtures) -- that is
97	# where a stale or forged hash is actually checkable, and a mismatch the pin
98	# cannot justify still fails there.
99	function Test-PluginsHashMatches([string]$PluginsFile, [string]$Expected, [string]$EvidenceFile) {
100	    if (-not (Test-Path -LiteralPath $PluginsFile -PathType Leaf) -or
101	        (Get-Item -LiteralPath $PluginsFile -Force).LinkType) { return $false }
102	    if ((Get-Sha256 $PluginsFile) -eq $Expected) { return $true }
103	    if (-not (Test-PluginsGitHistoryAvailable)) { return $true }
104	    $prefix = $RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
105	    if (-not $PluginsFile.StartsWith($prefix, [StringComparison]::Ordinal)) { return $false }
106	    $pluginsRelative = $PluginsFile.Substring($prefix.Length).Replace("\", "/")
107	    $pin = Get-PluginsPinCommit $EvidenceFile
108	    if (-not $pin) { return $false }
109	    $historical = Get-PluginsHashAtPin $pin $pluginsRelative
110	    if (-not $historical) { return $false }
111	    return $historical -eq $Expected
112	}
113	
114	# The amendment re-review lane (spec-review's own "## Amendment Re-Review
115	# Context" section, extended to impl/task in reviewer-calibration.md)
116	# creates a structural oscillation none of the tolerances above cover: each
117	# downstream stage's OWN recovery legitimately appends to the SAME
118	# specs/<feature>/investigation.md section that an UPSTREAM stage's
119	# reviewer manifest already pinned (investigation.md is an allowed input
120	# for all three stages -- see Test-ManifestPaths' unconditional allowance).
121	# That re-stales the upstream pin with a change whose entire content is the
122	# record of the very recovery the lane exists to permit -- not a change to
123	# anything reviewed. Unlike Stop-WorkflowStateOrTolerate below, this must
124	# work STANDALONE (no --opening): the oscillation bites precisely when no
125	# stage is currently being opened. Scoping this to one named section is
126	# what makes a standalone, unconditional tolerance safe: the section is the
127	# lane's own declared channel, its conformance is judged by every reviewer
128	# who reads investigation.md as part of that stage's normal review, and the
129	# checks below guarantee nothing outside that section -- and no mutation of
130	# an already-reviewed line inside it -- can ride through this path. See the
131	# Bash twin (check-workflow-state.sh) for the full reasoning; kept in
132	# parity here, not duplicated verbatim in every comment.
133	#
134	# Assumes LF-only line endings, consistent with this repo's markdown files
135	# and with every other line array this script builds; a CRLF
136	# investigation.md is out of scope for this reconciliation (unlike the
137	# tasks.md/CRLF handling elsewhere in this file, which predates it).
138	#
139	# Mirrors amendment_section_bounds in the Bash twin: returns @(start, end)
140	# (0-based, inclusive -- PowerShell array convention, unlike the Bash
141	# twin's 1-based line numbers) for the FIRST line reading exactly
142	# "## Amendment Re-Review Context" in $Lines, or $null if absent.
143	function Get-AmendmentSectionBounds([string[]]$Lines) {
144	    $start = -1
145	    for ($i = 0; $i -lt $Lines.Count; $i++) {
146	        if ($Lines[$i] -ceq "## Amendment Re-Review Context") { $start = $i; break }
147	    }
148	    if ($start -lt 0) { return $null }
149	    $end = $Lines.Count - 1
150	    for ($i = $start + 1; $i -lt $Lines.Count; $i++) {
151	        if ($Lines[$i] -clike "## *") { $end = $i - 1; break }
152	    }
153	    return @($start, $end)
154	}
155	# Case-sensitive, ordered, exact array equality -- used everywhere below
156	# instead of Compare-Object so a length mismatch and a content mismatch are
157	# both a plain $false, with no SideIndicator bookkeeping to misread.
158	function Test-LineArraysEqual([string[]]$A, [string[]]$B) {
159	    if ($A.Count -ne $B.Count) { return $false }
160	    for ($i = 0; $i -lt $A.Count; $i++) {
161	        if ($A[$i] -cne $B[$i]) { return $false }
162	    }
163	    return $true
164	}
165	# Mirrors investigation_growth_only_change in the Bash twin exactly --
166	# verifies the ONLY difference between $PinnedLines and $LiveLines is pure,
167	# contiguous growth confined to the "## Amendment Re-Review Context"
168	# section as computed on $LiveLines. See the Bash function's own comments
169	# for the full (1)-(4) reasoning (prefix identity, growth-only /
170	# no-mutation section body, EOF-only creation, suffix identity); this is
171	# the same logic in 0-based form.
172	function Test-InvestigationGrowthOnlyChange([string[]]$PinnedLines, [string[]]$LiveLines) {
173	    $liveBounds = Get-AmendmentSectionBounds $LiveLines
174	    if ($null -eq $liveBounds) { return $false }
175	    $liveStart = $liveBounds[0]
176	    $liveEnd = $liveBounds[1]
177	    $liveTotal = $LiveLines.Count
178	    $pinnedTotal = $PinnedLines.Count
179	
180	    $pinnedBounds = Get-AmendmentSectionBounds $PinnedLines
181	    if ($null -ne $pinnedBounds) {
182	        $pinnedStart = $pinnedBounds[0]
183	        $pinnedEnd = $pinnedBounds[1]
184	        # Sanity check, made explicit rather than left implicit in the
185	        # prefix comparison: the section must start at the same absolute
186	        # line in both files.
187	        if ($pinnedStart -ne $liveStart) { return $false }
188	        if ($liveStart -gt 0) {
189	            if (-not (Test-LineArraysEqual $PinnedLines[0..($liveStart - 1)] $LiveLines[0..($liveStart - 1)])) {
190	                return $false
191	            }
192	        }
193	    } else {
194	        # No fixed offset to compare against: the heading's live position is
195	        # unconstrained beyond "strictly after all of pinned's own content"
196	        # (a conventional blank-line separator before a brand-new heading
197	        # is itself new content, with nothing pinned to compare it
198	        # against), so the prefix check here compares ALL of pinned against
199	        # live's own first $pinnedTotal lines, not a window sized by
200	        # $liveStart.
201	        if ($liveStart -lt $pinnedTotal) { return $false }
202	        if ($pinnedTotal -gt 0) {
203	            if (-not (Test-LineArraysEqual $PinnedLines[0..($pinnedTotal - 1)] $LiveLines[0..($pinnedTotal - 1)])) {
204	                return $false
205	            }
206	        }
207	        # Created-at-EOF requirement, literal: the section must reach the
208	        # live file's own last line -- a brand-new section spliced ahead of
209	        # pre-existing trailing content is rejected even though it would
210	        # still pass a bare prefix/suffix-identity check.
211	        if ($liveEnd -ne ($liveTotal - 1)) { return $false }
212	    }
213	
214	    if ($null -ne $pinnedBounds) {
215	        $pinnedStart = $pinnedBounds[0]
216	        $pinnedEnd = $pinnedBounds[1]
217	        $pinnedSectionLen = $pinnedEnd - $pinnedStart + 1
218	        $liveSectionLen = $liveEnd - $liveStart + 1
219	        if ($liveSectionLen -lt $pinnedSectionLen) { return $false }
220	        $pinnedSection = $PinnedLines[$pinnedStart..$pinnedEnd]
221	        $liveSectionHead = $LiveLines[$liveStart..($liveStart + $pinnedSectionLen - 1)]
222	        if (-not (Test-LineArraysEqual $pinnedSection $liveSectionHead)) { return $false }
223	
224	        $pinnedAfter = $pinnedTotal - 1 - $pinnedEnd
225	        $liveAfter = $liveTotal - 1 - $liveEnd
226	        if ($pinnedAfter -gt 0 -or $liveAfter -gt 0) {
227	            if ($pinnedAfter -ne $liveAfter) { return $false }
228	            if ($pinnedAfter -gt 0) {
229	                $pinnedSuffix = $PinnedLines[($pinnedEnd + 1)..($pinnedTotal - 1)]
230	                $liveSuffix = $LiveLines[($liveEnd + 1)..($liveTotal - 1)]
231	                if (-not (Test-LineArraysEqual $pinnedSuffix $liveSuffix)) { return $false }
232	            }
233	        }
234	    }
235	    return $true
236	}
237	# Mirrors resolve_verified_investigation_pin in the Bash twin: resolves the
238	# pinned bytes of specs/<feature>/investigation.md at $Contract's
239	# introducing commit (Get-PluginsPinCommit/Get-PluginsHashAtPin -- the SAME
240	# machinery plugins/ reference docs use, reused rather than duplicated) and
241	# writes them to $OutFile. Returns $true only after independently
242	# re-verifying the written bytes' own sha256 equals $Expected -- a forged
243	# pin, an ambiguous introducing commit, or an unreconstructable history all
244	# fail here with nothing written that the caller could diff against.
245	function Resolve-VerifiedInvestigationPin([string]$Contract, [string]$Expected, [string]$Relative, [string]$OutFile) {
246	    $pin = Get-PluginsPinCommit $Contract
247	    if (-not $pin) { return $false }
248	    $historical = Get-PluginsHashAtPin $pin $Relative
249	    if ($historical -ne $Expected) { return $false }
250	    & git -C $ScriptRoot show "${pin}:${Relative}" > $OutFile 2>$null
251	    if ($LASTEXITCODE -ne 0) { return $false }
252	    return (Get-Sha256 $OutFile) -eq $Expected
253	}
254	# Mirrors investigation_amendment_reconciles in the Bash twin: the
255	# top-level entry point, applied uniformly to every stage (spec/impl/task)
256	# since investigation.md is an allowed input for all three and the
257	# oscillation is structurally identical regardless of which stage's pin
258	# went stale.
259	function Test-InvestigationAmendmentReconciles([string]$ManifestFile, [string]$Expected, [string]$Contract) {
260	    $prefix = $RepoRoot.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
261	    if (-not $ManifestFile.StartsWith($prefix, [StringComparison]::Ordinal)) { return $false }
262	    $relative = $ManifestFile.Substring($prefix.Length).Replace("\", "/")
263	    # WFI-024's no-history rule, extended to this reconciliation: without
264	    # git history the pinned generation's bytes are unreconstructable, so
265	    # the growth-only property is not evaluable -- accepted, not evaluated,
266	    # matching Test-PluginsHashMatches in a history-less tree.
267	    if (-not (Test-PluginsGitHistoryAvailable)) { return $true }
268	    $tempFile = [IO.Path]::GetTempFileName()
269	    try {
270	        if (-not (Resolve-VerifiedInvestigationPin $Contract $Expected $relative $tempFile)) { return $false }
271	        $pinnedLines = @(Get-Content -LiteralPath $tempFile)
272	        $liveLines = @(Get-Content -LiteralPath $ManifestFile)
273	        return Test-InvestigationGrowthOnlyChange $pinnedLines $liveLines
274	    } finally {
275	        Remove-Item -LiteralPath $tempFile -Force -ErrorAction SilentlyContinue
276	    }
277	}
