285	function Get-NormalizedHash([string]$Path, [string]$Stage) {
286	    $text = [IO.File]::ReadAllText($Path)
287	    switch ($Stage) {
288	        "spec" {
289	            $text = [regex]::Replace(
290	                $text, "(?m)^Spec-Review-Status:[^\r\n]*(\r?)$", 'Spec-Review-Status: Pending$1')
291	        }
292	        "impl" {
293	            $text = [regex]::Replace(
294	                $text, "(?m)^Impl-Review-Status:[^\r\n]*(\r?)$", 'Impl-Review-Status: Pending$1')
295	        }
296	        "task" {
297	            $text = [regex]::Replace(
298	                $text, "(?m)^Task-Review-Status:[^\r\n]*(\r?)$", 'Task-Review-Status: Pending$1')
299	            $text = [regex]::Replace(
300	                $text, "(?m)^Approval:[^\r\n]*(\r?)$", 'Approval: Draft$1')
301	            $text = [regex]::Replace(
302	                $text, "(?m)^Status:[^\r\n]*(\r?)$", 'Status: Planned$1')
303	                $text = [regex]::Replace(
304	                    $text, "(?m)^Second Approval:[^\r\n]*\r?\n?", '')
305	        }
306	    }
307	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
308	    $sha = [Security.Cryptography.SHA256]::Create()
309	    # PS5.1-safe (no [Convert]::ToHexString, .NET 5+ only).
310	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
311	    finally { $sha.Dispose() }
312	}
313	function Get-RereviewNormalizedHash([string]$Path, [string]$Status) {
314	    $text = [IO.File]::ReadAllText($Path)
315	    $text = [regex]::Replace($text, "(?m)^Task-Review-Status:[^\r\n]*(\r?)$", 'Task-Review-Status: Passed$1')
316	    $text = [regex]::Replace($text, "(?m)^Approval:[^\r\n]*(\r?)$", 'Approval: Approved$1')
317	    $text = [regex]::Replace($text, "(?m)^Status:[^\r\n]*(\r?)$", "Status: ${Status}`$1")
318	    $text = [regex]::Replace($text, "(?m)^Second Approval:[^\r\n]*\r?\n?", '')
319	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
320	    $sha = [Security.Cryptography.SHA256]::Create()
321	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
322	    finally { $sha.Dispose() }
323	}
324	# Twin of traceability_normalized_hash() in check-workflow-state.sh. Rewrites
325	# only each REQ row's final delivery-status cell, and only over the closed
326	# lifecycle vocabulary; every other byte still participates in the digest.
327	# [^\S\r\n] is horizontal whitespace only, so the explicit (\r?)$ keeps CRLF
328	# input byte-identical -- matching the convention of the functions above.
329	function Get-TraceabilityNormalizedHash([string]$Path) {
330	    $text = [IO.File]::ReadAllText($Path)
331	    $text = [regex]::Replace(
332	        $text,
333	        '(?m)^(\|[^\S\r\n]*REQ-.*\|)([^\S\r\n]*)(Planned|In Progress|Implementation Complete|Done|Blocked)([^\S\r\n]*\|[^\S\r\n]*)(\r?)$',
334	        '${1}${2}Planned${4}${5}')
335	    $bytes = [Text.UTF8Encoding]::new($false).GetBytes($text)
336	    $sha = [Security.Cryptography.SHA256]::Create()
337	    try { return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "").ToLowerInvariant() }
338	    finally { $sha.Dispose() }
339	}
