733	        $leftNames = @($Left.PSObject.Properties.Name | Sort-Object)
734	        $rightNames = @($Right.PSObject.Properties.Name | Sort-Object)
735	        if (($leftNames -join "`t") -cne ($rightNames -join "`t")) { return $false }
736	        foreach ($name in $leftNames) {
