740	    }
741	    $leftIsArray = $Left -is [array]
742	    $rightIsArray = $Right -is [array]
743	    if ($leftIsArray -or $rightIsArray) {
744	        if (-not ($leftIsArray -and $rightIsArray) -or $Left.Count -ne $Right.Count) { return $false }
745	        for ($i = 0; $i -lt $Left.Count; $i++) {
746	            if (-not (Test-JsonValueEqual $Left[$i] $Right[$i])) { return $false }
747	        }
748	        return $true
749	    }
750	    return $Left -ceq $Right
751	}
752	# PS5.1-safe (no Test-Json, unavailable before PowerShell 6.1): mirrors the
753	# hand-rolled structural check in the bash twin (check-workflow-state.sh)
754	# rather than general JSON Schema validation, so both stay in parity and
755	# neither depends on a cmdlet this repo's Windows hosts don't have.
756	function Test-RegistrySchema($RegistryData, [string]$SchemaPath) {
757	    try { $schema = Get-Content -LiteralPath $SchemaPath -Raw | ConvertFrom-Json }
758	    catch { return $false }
759	    $topKeys = @($RegistryData.PSObject.Properties.Name | Sort-Object)
760	    if (($topKeys -join "`t") -cne (@("entries", "migration_baseline_commit", "schema_version") -join "`t")) {
761	        return $false
762	    }
763	    if (-not (Test-JsonValueEqual $RegistryData.schema_version $schema.properties.schema_version.const) -or
764	        -not (Test-JsonValueEqual $RegistryData.migration_baseline_commit $schema.properties.migration_baseline_commit.const)) {
765	        return $false
766	    }
767	    # The jq twin requires .entries to be a JSON array; @() coercion alone
768	    # would let a scalar entries object pass as a one-item list.
769	    if ($RegistryData.entries -isnot [array]) { return $false }
770	    $entries = @($RegistryData.entries)
771	    if ($entries.Count -eq 0) { return $false }
772	    $legacyConsts = @($schema.definitions.legacyEntry.oneOf | ForEach-Object { $_.const })
773	    foreach ($entry in $entries) {
774	        $entryProfile = [string]$entry.profile
775	        if ($entryProfile -eq "full" -or $entryProfile -eq "lite") {
776	            $entryKeys = @($entry.PSObject.Properties.Name | Sort-Object)
777	            if (($entryKeys -join "`t") -cne (@("feature", "profile") -join "`t")) { return $false }
778	        } else {
779	            $matched = $false
780	            foreach ($candidate in $legacyConsts) {
781	                if (Test-JsonValueEqual $entry $candidate) { $matched = $true; break }
782	            }
783	            if (-not $matched) { return $false }
784	        }
785	    }
786	    return $true
787	}
788	
789	$Schema = Join-Path $ScriptRoot "contracts/workflow-state-registry.schema.json"
790	if (-not (Test-Path -LiteralPath $Schema -PathType Leaf)) {
791	    Stop-WorkflowState "repository" "registry-schema" "registry schema is unavailable"
792	}
793	if (-not (Test-RegistrySchema $RegistryData $Schema)) {
