795	}
796	
797	$SpecsRoot = (Resolve-Path (Split-Path -Parent $Registry)).Path
798	$RepoRoot = (Resolve-Path (Join-Path $SpecsRoot "..")).Path
799	$duplicate = @($RegistryData.entries | Group-Object feature | Where-Object Count -gt 1 | Select-Object -First 1)
800	if ($duplicate) { Stop-WorkflowState $duplicate[0].Name "registry-duplicate" "feature is registered more than once" }
801	$declared = @{}
802	$script:RegistryFailedFeatures = @{}
803	foreach ($entry in @($RegistryData.entries)) {
