809	        if (-not (Test-Path -LiteralPath $candidate -PathType Container)) {
810	            Stop-WorkflowState $feature "registry-dangling-entry" "registered specification directory is missing"
811	        }
812	        $item = Get-Item -LiteralPath $candidate -Force
813	        if ($item.LinkType) {
