819	        }
820	        $prefix = $SpecsRoot.TrimEnd([IO.Path]::DirectorySeparatorChar) + [IO.Path]::DirectorySeparatorChar
821	        if (-not ($resolved + [IO.Path]::DirectorySeparatorChar).StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) {
822	            Stop-WorkflowState $feature "registry-path-escape" "registered directory escapes specs root"
823	        }
824	        if ($item.LinkType) {
825	            Stop-WorkflowState $feature "registry-linked-entry" "registered specification directory must not be linked"
826	        }
827	    } catch {
828	        if ([string]$_.Exception.Message -ne $script:WorkflowStateFeatureAbort) { throw }
829	        $script:WorkflowStateFailed++
830	        $script:RegistryFailedFeatures[$feature] = $true
831	    } finally {
832	        $script:FeatureScopeActive = $false
833	    }
834	}
835	foreach ($directory in @(Get-ChildItem -LiteralPath $SpecsRoot -Directory -Force)) {
836	    if (-not $declared.ContainsKey($directory.Name)) {
837	        Write-WorkflowStateDiagnostic $directory.Name "registry-unregistered-directory" "specification directory is not registered"
838	        $script:WorkflowStateFailed++
839	    }
840	}
841	if ($FeatureFilter -and -not $declared.ContainsKey($FeatureFilter)) {
842	    Stop-WorkflowState $FeatureFilter "registry-unknown-feature" "feature is not registered"
843	}
844	
845	# A BLOCKED or NEEDS_WORK verdict is the terminal state of one review pass,
846	# not necessarily of the stage: a caller can re-open review after it (a
847	# fresh attempt, or another round of the same attempt), and it is that later
848	# pass -- not the one it superseded -- whose outcome the stage should be
849	# judged on while it is still running.
850	#
851	# A tree-only signal cannot express this: the gate that must pass before a
852	# new round is created runs BEFORE that round's own directory exists (this
853	# is precisely what impl-review-precheck.sh's own replay guard requires --
854	# "round destination already exists" is fatal), so nothing on disk can ever
855	# prove a round is "open" at the one moment this check needs to know it. An
856	# earlier version of this fix looked for a precheck-result.json in a later
857	# round directory; that file cannot exist yet either, for the same reason,
858	# so the exemption could never fire for the caller it exists for.
859	#
860	# The distinction that actually matters is who is asking, not what the tree
861	# looks like right now (same conflation as before, resolved one level up).
862	# A review-loop precheck opening round (attempt, round) knows those numbers
863	# as its own CLI arguments -- ATTEMPT and ROUND -- before it ever reaches
864	# this gate, and it is asking "may I start?", not "did this conclude?". It
865	# says so explicitly via -Opening stage:attempt:round. A standalone
866	# invocation (CI, task-state-check, anything auditing the feature's health)
867	# never passes -Opening and gets none of this exemption: the latest verdict
868	# governs for it exactly as before, unconditionally.
869	#
870	# -Opening is not "a flag anyone can pass to wave away a BLOCKED verdict",
871	# because it does not assert "trust me, this stage is fine" -- it names one

